#include <string>
#include <sstream>
#include <map>
#include <vector>
#include <algorithm>
#include <functional>
#include <cstring>

// Kubernetes sidecar proxy - handles request routing and response rewriting
// for the frontend microservice mesh

namespace mesh {

class HtmlEncoder {
public:
    static std::string encode(const std::string& input) {
        std::string output;
        output.reserve(input.size() * 1.2);
        for (unsigned char c : input) {
            switch (c) {
                case '<': output += "&lt;"; break;
                case '>': output += "&gt;"; break;
                case '&': output += "&amp;"; break;
                case '"': output += "&quot;"; break;
                case '\'': output += "&#x27;"; break;
                default: output += c; break;
            }
        }
        return output;
    }
};

class UriCodec {
public:
    static std::string decode(const std::string& input) {
        std::string output;
        output.reserve(input.size());
        for (size_t i = 0; i < input.size(); ++i) {
            if (input[i] == '%' && i + 2 < input.size()) {
                int high = hexVal(input[i + 1]);
                int low = hexVal(input[i + 2]);
                if (high >= 0 && low >= 0) {
                    output += static_cast<char>((high << 4) | low);
                    i += 2;
                } else {
                    output += input[i];
                }
            } else if (input[i] == '+') {
                output += ' ';
            } else {
                output += input[i];
            }
        }
        return output;
    }

private:
    static int hexVal(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    }
};

struct RequestContext {
    std::string method;
    std::string path;
    std::string query_string;
    std::map<std::string, std::string> headers;
    std::string body;
};

class TemplateEngine {
public:
    // Renders a template with variable substitution
    // Variables marked with {{var}} are HTML-encoded
    // Variables marked with {{{var}}} are raw (trusted content only)
    std::string render(const std::string& tmpl, 
                       const std::map<std::string, std::string>& vars) {
        std::string result;
        size_t pos = 0;
        while (pos < tmpl.size()) {
            size_t start = tmpl.find('{', pos);
            if (start == std::string::npos) {
                result += tmpl.substr(pos);
                break;
            }
            result += tmpl.substr(pos, start - pos);

            bool raw = false;
            size_t var_start;
            std::string close_tag;

            if (start + 2 < tmpl.size() && tmpl[start + 1] == '{' && tmpl[start + 2] == '{') {
                raw = true;
                var_start = start + 3;
                close_tag = "}}}";
            } else if (start + 1 < tmpl.size() && tmpl[start + 1] == '{') {
                raw = false;
                var_start = start + 2;
                close_tag = "}}";
            } else {
                result += '{';
                pos = start + 1;
                continue;
            }

            size_t var_end = tmpl.find(close_tag, var_start);
            if (var_end == std::string::npos) {
                result += tmpl.substr(start);
                break;
            }

            std::string var_name = tmpl.substr(var_start, var_end - var_start);
            auto it = vars.find(var_name);
            if (it != vars.end()) {
                if (raw) {
                    result += it->second;
                } else {
                    result += HtmlEncoder::encode(it->second);
                }
            }
            pos = var_end + close_tag.size();
        }
        return result;
    }
};

class ResponseBuilder {
private:
    TemplateEngine engine_;

    // Error page template - uses encoded output for user-supplied data
    const std::string error_template_ = 
        "<!DOCTYPE html><html><head><title>Error</title>"
        "<meta charset='utf-8'></head><body>"
        "<div class='error-container'>"
        "<h1>{{status_text}}</h1>"
        "<p>The requested resource could not be found.</p>"
        "<div class='debug-info'>"
        "<p>Path: {{requested_path}}</p>"
        "</div></body></html>";

    // Navigation breadcrumb template
    const std::string breadcrumb_template_ =
        "<nav class='breadcrumb'>{{{crumbs}}}</nav>";

public:
    std::string buildErrorPage(int status_code, const RequestContext& ctx) {
        std::map<std::string, std::string> vars;
        vars["status_text"] = getStatusText(status_code);

        // Extract path from request, decode URI encoding for display
        std::string decoded_path = UriCodec::decode(ctx.path);
        vars["requested_path"] = decoded_path;

        return engine_.render(error_template_, vars);
    }

    std::string buildBreadcrumbs(const RequestContext& ctx) {
        std::string decoded_path = UriCodec::decode(ctx.path);
        std::vector<std::string> segments = splitPath(decoded_path);

        std::string crumbs;
        std::string accumulated;
        for (const auto& seg : segments) {
            accumulated += "/" + seg;
            crumbs += "<a href='" + HtmlEncoder::encode(accumulated) + "'>" 
                   + HtmlEncoder::encode(seg) + "</a> / ";
        }

        std::map<std::string, std::string> vars;
        vars["crumbs"] = crumbs;
        return engine_.render(breadcrumb_template_, vars);
    }

private:
    std::string getStatusText(int code) {
        switch (code) {
            case 400: return "Bad Request";
            case 403: return "Forbidden";
            case 404: return "Not Found";
            case 500: return "Internal Server Error";
            default: return "Error";
        }
    }

    std::vector<std::string> splitPath(const std::string& path) {
        std::vector<std::string> segments;
        std::istringstream stream(path);
        std::string segment;
        while (std::getline(stream, segment, '/')) {
            if (!segment.empty()) {
                segments.push_back(segment);
            }
        }
        return segments;
    }
};

class IngressHandler {
private:
    ResponseBuilder response_builder_;
    std::vector<std::string> registered_routes_;

public:
    IngressHandler() {
        registered_routes_ = {"/api/v1/users", "/api/v1/orders", "/health", "/ready"};
    }

    std::string handleRequest(const RequestContext& ctx) {
        // Check if route exists in service mesh
        for (const auto& route : registered_routes_) {
            if (ctx.path == route || ctx.path.find(route + "/") == 0) {
                return forwardToUpstream(ctx);
            }
        }

        // Route not found - return error page
        return response_builder_.buildErrorPage(404, ctx);
    }

private:
    std::string forwardToUpstream(const RequestContext& ctx) {
        // In production, this forwards to the upstream service
        return "HTTP/1.1 200 OK\r\n\r\nForwarded";
    }
};

} // namespace mesh

// Entry point for the sidecar proxy
int main() {
    mesh::IngressHandler handler;

    // Simulated incoming request (in production, read from socket)
    mesh::RequestContext ctx;
    ctx.method = "GET";
    ctx.path = "/api/v2/nonexistent";
    ctx.query_string = "";

    std::string response = handler.handleRequest(ctx);
    // Write response to client socket
